mapper.select:
SELECT id, blocker_user_id, blocked_user_id, status, created_at, updated_at
FROM `contact_block`
WHERE blocker_user_id = #{blockerUserId}
  AND blocked_user_id = #{blockedUserId}
LIMIT 1

mapper.insert:
INSERT INTO `contact_block` (
    id, blocker_user_id, blocked_user_id, status, created_at, updated_at
) VALUES (
    #{id}, #{blockerUserId}, #{blockedUserId}, #{status}, #{createdAt}, #{updatedAt}
)
